const fs = require('fs');

const data = fs.readFileSync('/dev/stdin', 'utf8').trim().split(/\s+/).map(Number);
const V = data[0];
const contas = [data[1], data[2], data[3]].sort((a, b) => a - b);

let restante = V;
let count = 0;

for (const c of contas) {
    if (c <= restante) {
        restante -= c;
        count++;
    } else {
        break;
    }
}

console.log(count);
